#!/usr/bin/env bash
# Generated by pipeline_compiler. nvinfer_backport must be on the GStreamer
# plugin path (verify: gst-inspect-1.0 nvinfer_backport). Override CAM /
# CAM_W / CAM_H / CAM_FPS / CAM_FMT via env to match your camera's
# supported capture modes (`v4l2-ctl --list-formats-ext -d <device>`).
set -euo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# ── VMS mode ──────────────────────────────────────────────────────
# Generated from run.sh. Same sources, models, tracker and boxes — only
# the sink differs: instead of a window or a file this serves
#     video     tcp://0.0.0.0:${VMS_MJPEG_PORT}   multipart MJPEG
#     metadata  tcp://0.0.0.0:${VMS_META_PORT}    newline JSON
# and appends every logged frame to ${VMS_ROOT}/events/cam<N>.jsonl.
# Connect the console with:  python3 vms_console.py --host 127.0.0.1
# Start this FIRST, or just leave the console open — it reconnects.
export VMS_ROOT="${VMS_ROOT:-${DIR}/store}"
export VMS_MIN_CONF="${VMS_MIN_CONF:-0.3}"
export VMS_INTERVAL="${VMS_INTERVAL:-5}"
export VMS_SKIP_EMPTY="${VMS_SKIP_EMPTY:-1}"
export VMS_STATUS="${VMS_STATUS:-2.0}"
export VMS_META_PORT="${VMS_META_PORT:-7002}"
export VMS_MJPEG_PORT="${VMS_MJPEG_PORT:-7010}"
export VMS_JPEG_QUALITY="${VMS_JPEG_QUALITY:-80}"
export VMS_MAX_SHAPES="${VMS_MAX_SHAPES:-64}"
mkdir -p "${VMS_ROOT}/events" 2>/dev/null || true
echo "[run.vms.sh] video tcp://0.0.0.0:${VMS_MJPEG_PORT}  metadata tcp://0.0.0.0:${VMS_META_PORT}" >&2


CAM="${CAM:-/dev/video0}"
CAM_W=${CAM_W:-1920}
CAM_H=${CAM_H:-1080}
CAM_FPS=${CAM_FPS:-30}
CAM_FMT="${CAM_FMT:-YUYV}"

# ── Metadata sink config ──────────────────────────────────────────
# Read by the nvcustomprocess user libraries in build/ (the element
# has no config-file property). Override any of these at run time:
#   MQTT_HOST=10.0.0.9 ./run.sh      JSON_OUT=/tmp/d.json ./run.sh
# MQTT needs a reachable broker. None running? Start the one that
# ships with DeepStream:  /usr/local/sbin/mosquitto -p ${MQTT_PORT} &
# A missing broker never fails the pipeline — the video still runs
# and the library reports that it published nothing.
export JSON_OUT="${JSON_OUT:-/home/paradox/.pipegen/shlokbagul4/701662e6-fc31-46d2-b2c5-e0d2acc4fcf0/output/metadata.json}"
export JSON_MIN_CONF="${JSON_MIN_CONF:-0.0}"
export MQTT_HOST="${MQTT_HOST:-localhost}"
export MQTT_PORT="${MQTT_PORT:-1883}"
export MQTT_TOPIC="${MQTT_TOPIC:-sentinel/alerts}"
export MQTT_QOS="${MQTT_QOS:-0}"
export MQTT_CLIENT_ID="${MQTT_CLIENT_ID:-pipegen-detection-12208078-1080-1920-60f-$$}"
export MQTT_KEEPALIVE="${MQTT_KEEPALIVE:-60}"
export MQTT_INTERVAL="${MQTT_INTERVAL:-1}"
export MQTT_SKIP_EMPTY="${MQTT_SKIP_EMPTY:-0}"
export MQTT_PAYLOAD="${MQTT_PAYLOAD:-frame}"
export MQTT_MIN_CONF="${MQTT_MIN_CONF:-0.0}"
export MQTT_STATUS="${MQTT_STATUS:-0.5}"
export JSON_MASK_OUTLINE="${JSON_MASK_OUTLINE:-0}"
cat >&2 <<MQTTHELP

  ── Publishing detections over MQTT ──────────────────────────
  Broker : ${MQTT_HOST}:${MQTT_PORT}
  Topic  : ${MQTT_TOPIC}

  To CHECK messages are arriving — start it BEFORE the pipeline,
  because messages sent while nobody is listening are discarded,
  not queued.

  From this machine (nothing to install):
      docker run --rm --network host --entrypoint mosquitto_sub craftifaidocker/deepstream:7.1-${DS_ARCH:-amd64}-v3 -h ${MQTT_HOST} -p ${MQTT_PORT} -t '${MQTT_TOPIC}' -v

  From any machine that has the mosquitto clients installed:
      mosquitto_sub -h ${MQTT_HOST} -p ${MQTT_PORT} -t '${MQTT_TOPIC}' -v

  To USE it, subscribe to that topic from your own program. One
  JSON message per frame: frame number, camera id, timestamp, and
  a list of objects — each with a label, a tracking id that
  follows it between frames, a confidence and a bounding box.

  Change the broker without rebuilding:
      MQTT_HOST=10.0.0.9 ./run.sh
  ─────────────────────────────────────────────────────────────

MQTTHELP
mkdir -p "$(dirname "${JSON_OUT}")" 2>/dev/null || true
echo "[run.sh] JSON -> ${JSON_OUT}" >&2

if [ -f "${DIR}/parsers/Makefile" ] && command -v make >/dev/null 2>&1; then
  make -C "${DIR}/parsers" || { echo "parser/.so build failed" >&2; exit 1; }
fi

gst-launch-1.0 -e nvstreammux name=mux batch-size=1 width=1920 height=1080 batched-push-timeout=33000 live-source=1 nvurisrcbin uri="file:///home/paradox/videos/12208078_1080_1920_60fps.mp4" ! identity sync=true ! mux.sink_0 mux. ! queue max-size-buffers=4 ! nvvideoconvert ! queue max-size-buffers=4 ! nvinfer_backport config-file-path="${DIR}/configs/config_det_pgie.txt" ! queue max-size-buffers=4 ! nvtracker tracker-width=640 tracker-height=384 ll-lib-file=/opt/nvidia/deepstream/deepstream/lib/libnvds_nvmultiobjecttracker.so ll-config-file="${DIR}/configs/config_tracker.yml" display-tracking-id=1 ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path="${DIR}/build/libhazard_zone_render_process.so" process-func-name=NvDsCustomPostProcess ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path="${DIR}/build/libmeta_json.so" process-func-name=MetaJson ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path="${DIR}/build/libmqtt_publish.so" process-func-name=MqttPublish ! queue max-size-buffers=4 ! nvcustomprocess custom-lib-path=${DIR}/build/libvms_detect.so process-func-name=VmsDetect ! queue max-size-buffers=4 ! nvvideoconvert ! nvmultistreamtiler rows=1 columns=1 width=1920 height=1080 ! nvvideoconvert ! queue max-size-buffers=4 ! nvvideoconvert ! "video/x-raw,format=I420" ! jpegenc quality=${VMS_JPEG_QUALITY} ! multipartmux boundary=vmsframe ! tcpserversink host=0.0.0.0 port=${VMS_MJPEG_PORT} sync=false recover-policy=latest
